  3003	md_collect_marks(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines, int table_mode)
  3004	{
  3005	    MD_SIZE line_index;
  3006	    int ret = 0;
  3007	    MD_MARK* mark;
  3008	    OFF codespan_last_potential_closers[CODESPAN_MARK_MAXLEN] = { 0 };
  3009	    int codespan_scanned_till_paragraph_end = FALSE;
  3010	
  3011	    for(line_index = 0; line_index < n_lines; line_index++) {
  3012	        const MD_LINE* line = &lines[line_index];
  3013	        OFF off = line->beg;
  3014	
  3015	        while(TRUE) {
  3016	            CHAR ch;
  3017	
  3018	#ifdef MD4C_USE_UTF16
  3019	    /* For UTF-16, mark_char_map[] covers only ASCII. */
  3020	    #define IS_MARK_CHAR(off)   ((CH(off) < SIZEOF_ARRAY(ctx->mark_char_map))  &&  \
  3021	                                (ctx->mark_char_map[(unsigned char) CH(off)]))
  3022	#else
  3023	    /* For 8-bit encodings, mark_char_map[] covers all 256 elements. */
  3024	    #define IS_MARK_CHAR(off)   (ctx->mark_char_map[(unsigned char) CH(off)])
  3025	#endif
  3026	
  3027	            /* Optimization: Use some loop unrolling. */
  3028	            while(off + 3 < line->end  &&  !IS_MARK_CHAR(off+0)  &&  !IS_MARK_CHAR(off+1)
  3029	                                       &&  !IS_MARK_CHAR(off+2)  &&  !IS_MARK_CHAR(off+3))
  3030	                off += 4;
  3031	            while(off < line->end  &&  !IS_MARK_CHAR(off+0))
  3032	                off++;
  3033	
  3034	            if(off >= line->end)
  3035	                break;
  3036	
  3037	            ch = CH(off);
  3038	
  3039	            /* A backslash escape.
  3040	             * It can go beyond line->end as it may involve escaped new
  3041	             * line to form a hard break. */
  3042	            if(ch == _T('\\')  &&  off+1 < ctx->size  &&  (ISPUNCT(off+1) || ISNEWLINE(off+1))) {
  3043	                /* Hard-break cannot be on the last line of the block. */
  3044	                if(!ISNEWLINE(off+1)  ||  line_index+1 < n_lines)
  3045	                    ADD_MARK(ch, off, off+2, MD_MARK_RESOLVED);
  3046	                off += 2;
  3047	                continue;
  3048	            }
  3049	
  3050	            /* A potential (string) emphasis start/end. */
  3051	            if(ch == _T('*')  ||  ch == _T('_')) {
  3052	                OFF tmp = off+1;
  3053	                int left_level;     /* What precedes: 0 = whitespace; 1 = punctuation; 2 = other char. */
  3054	                int right_level;    /* What follows: 0 = whitespace; 1 = punctuation; 2 = other char. */
  3055	
  3056	                while(tmp < line->end  &&  CH(tmp) == ch)
  3057	                    tmp++;
  3058	
  3059	                if(off == line->beg  ||  ISUNICODEWHITESPACEBEFORE(off))
  3060	                    left_level = 0;
  3061	                else if(ISUNICODEPUNCTBEFORE(off))
  3062	                    left_level = 1;
  3063	                else
  3064	                    left_level = 2;
  3065	
  3066	                if(tmp == line->end  ||  ISUNICODEWHITESPACE(tmp))
  3067	                    right_level = 0;
  3068	                else if(ISUNICODEPUNCT(tmp))
  3069	                    right_level = 1;
  3070	                else
  3071	                    right_level = 2;
  3072	
  3073	                /* Intra-word underscore doesn't have special meaning. */
  3074	                if(ch == _T('_')  &&  left_level == 2  &&  right_level == 2) {
  3075	                    left_level = 0;
  3076	                    right_level = 0;
  3077	                }
  3078	
  3079	                if(left_level != 0  ||  right_level != 0) {
  3080	                    unsigned flags = 0;
  3081	
  3082	                    if(left_level > 0  &&  left_level >= right_level)
  3083	                        flags |= MD_MARK_POTENTIAL_CLOSER;
  3084	                    if(right_level > 0  &&  right_level >= left_level)
  3085	                        flags |= MD_MARK_POTENTIAL_OPENER;
  3086	                    if(flags == (MD_MARK_POTENTIAL_OPENER | MD_MARK_POTENTIAL_CLOSER))
  3087	                        flags |= MD_MARK_EMPH_OC;
  3088	
  3089	                    /* For "the rule of three" we need to remember the original
  3090	                     * size of the mark (modulo three), before we potentially
  3091	                     * split the mark when being later resolved partially by some
  3092	                     * shorter closer. */
  3093	                    switch((tmp - off) % 3) {
  3094	                        case 0: flags |= MD_MARK_EMPH_MOD3_0; break;
  3095	                        case 1: flags |= MD_MARK_EMPH_MOD3_1; break;
  3096	                        case 2: flags |= MD_MARK_EMPH_MOD3_2; break;
  3097	                    }
  3098	
  3099	                    ADD_MARK(ch, off, tmp, flags);
  3100	
  3101	                    /* During resolving, multiple asterisks may have to be
  3102	                     * split into independent span start/ends. Consider e.g.
  3103	                     * "**foo* bar*". Therefore we push also some empty dummy
  3104	                     * marks to have enough space for that. */
  3105	                    off++;
  3106	                    while(off < tmp) {
  3107	                        ADD_MARK('D', off, off, 0);
  3108	                        off++;
  3109	                    }
  3110	                    continue;
  3111	                }
  3112	
  3113	                off = tmp;
  3114	                continue;
  3115	            }
  3116	
  3117	            /* A potential code span start/end. */
  3118	            if(ch == _T('`')) {
  3119	                MD_MARK opener;
  3120	                MD_MARK closer;
  3121	                int is_code_span;
  3122	
  3123	                is_code_span = md_is_code_span(ctx, line, n_lines - line_index, off,
  3124	                            &opener, &closer, codespan_last_potential_closers,
  3125	                            &codespan_scanned_till_paragraph_end);
  3126	                if(is_code_span) {
  3127	                    ADD_MARK(opener.ch, opener.beg, opener.end, opener.flags);
  3128	                    ADD_MARK(closer.ch, closer.beg, closer.end, closer.flags);
  3129	                    md_resolve_range(ctx, ctx->n_marks-2, ctx->n_marks-1);
  3130	                    off = closer.end;
